/**
 * A column of items of one kind, each read, followed or picked (`design/components/list.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  SlotOutlet,
  SlotTemplate,
  agentMember,
  chooseListItem,
  currentListItem,
  elementRef,
  listItems,
  mountEffect,
  useMember,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/list.module.css'

/** A column of items of one kind, each read, followed or picked: the inputs it takes, by the React member's prop names. */
export interface ListProps {
  /**
   * Names the list for a reader: "Notifications", not "List".
   */
  label: string
}

/** A column of items of one kind, each read, followed or picked. */
@Component({
  selector: 'pm-list',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, SlotOutlet, SlotTemplate],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<ul
[attr.class]="e1()"
role="list"
[attr.aria-label]="e2()"
data-member="list"
[pmRef]="list"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></ul>`,
})
export class List {
  /**
   * Names the list for a reader: "Notifications", not "List".
   */
  readonly label = input.required<ListProps['label']>()
  protected readonly $ = useMember({ events: [], props: { label: () => this.label() } })
  protected readonly $p = this.$.props
  protected readonly list = elementRef<HTMLElement>()
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return styles.list
  }

  protected e2() {
    return this.$p.label
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'List',
      element: () => this.list.value,
      state: () => ({
        items: listItems(this.list.value, styles.primary),
        current: currentListItem(this.list.value, styles.primary),
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) => chooseListItem(this.list.value, styles.primary, value),
        },
      },
    })
    this.release1 = () => {
      ran()
    }
  }
}
